BASE_DIR = "input"
OUTPUT_DIR = BASE_DIR + "_analyzed"
MODEL_NAME = "gemini-3.1-flash-lite" #gemini-3.5-flash, gemini-3.1-flash-lite, gemini-2.5-flash, gemma-4-31b-it
DELAY_SECONDS = 10
MAX_RETRIES = 10
MAX_DELAY_SECONDS = 600
CODING_INSTRUCTION = "This is a decompilers C-style reconstruction of a function from the executable of the video game Rome Total War. Describe this functions apparent purpose and role within the games systems. State only what is directly supported by code and data structures, but include high confidence inferences where appropriate. The description should be on the broader holistic level, not on that of particular implementation, except where they are necessary to identify the functions purpose. Return the response as a JSON object with exactly these fields: \"name\": a suggestion for a flatcase name to append to the function name. \"purpose\": a documentation annotation describing the functions apparent conceptual responsibility, the game concepts it operates on, what role it most likely serves within the games logic, and any high confidence inferences that would help distinguish it from similar functions. Prefer including useful context over brevity. Do not describe implementation details unless they are necessary to explain the conceptual role. Focus on what matters to the player, not the algorithmic housekeeping. \"domain\": the primary game system or engine domain this function belongs to. This is a category for sorting functions. \"keywords\": a comprehensive list of search terms that someone reverse engineering the game might later search for, including game concepts, mechanics, entities, systems, and closely related concepts. Include plausible synonyms where supported by the code. Do not overly focus on implementation terminology. \"modding\": a boolean that is true only if this function appears to define, compute, or directly apply a game mechanic that a reverse engineer would likely modify to intentionally change gameplay. Return false for wrappers, accessors, dispatchers, lookups, validation, state management, scripting infrastructure, rendering, UI, or other supporting functions, even if they participate in gameplay. \"arguments\": As far as possible to infer from this stripped code, provide a list of what arguments the function passes on to the functions it calls or what data they contain. This information is meant to later be included in the context when generating their annotations, so they can be generated with knowledge of what data is passed to them. State what is known at this time. Output a JSON object with no surrounding text, code fences, or headers."
#List what variables it sends to other functions, and propose names for those variables that better represent what data they likely contain, so that a function receiving this data would be able to take into account what the input is; but only to the degree this is inferable from the code.
